  'inventory.businessCapabilities.blurb': { en: 'What a system does for the business - Payroll, Treasury, etc. Assignable per system, and used to group the Stakeholder canvas view.', cs: 'Co systém pro firmu dělá - mzdy, treasury atd. Přiřaditelné pro každý systém, používá se ke seskupení v pohledu pro zainteresované strany.', de: 'Was ein System für das Unternehmen leistet - Gehaltsabrechnung, Treasury usw. Pro System zuweisbar, wird zur Gruppierung in der Stakeholder-Ansicht verwendet.', fi: 'Mitä järjestelmä tekee liiketoiminnalle - palkanlaskenta, rahoitus jne. Määritettävissä järjestelmäkohtaisesti, käytetään sidosryhmänäkymän ryhmittelyyn.' },

  // Reference item delete dialog
  'refDelete.title': { en: 'Delete "{name}"?', cs: 'Smazat „{name}“?', de: '„{name}“ löschen?', fi: 'Poistetaanko "{name}"?' },
  'refDelete.notUsed': { en: "This entry isn't used by any connection. This action can't be undone.", cs: 'Tato položka není použita v žádném propojení. Tuto akci nelze vrátit zpět.', de: 'Dieser Eintrag wird von keiner Verbindung verwendet. Diese Aktion kann nicht rückgängig gemacht werden.', fi: 'Tätä merkintää ei käytetä missään yhteydessä. Tätä toimintoa ei voi kumota.' },
  'refDelete.usedByFlows': { en: 'This is used by {count} connection {flows}. Deleting it would leave those flows untagged unless you resolve them first.', cs: 'Toto je použito v {count} propojeních ({flows}). Smazáním by tyto toky zůstaly neoznačené, pokud je nejprve nevyřešíte.', de: 'Dies wird von {count} Verbindung(en) ({flows}) verwendet. Beim Löschen blieben diese Flüsse unmarkiert, sofern Sie sie nicht vorher auflösen.', fi: 'Tätä käyttää {count} yhteyttä ({flows}). Poistaminen jättäisi nämä virrat merkitsemättä, ellet ratkaise niitä ensin.' },
  'refDelete.replaceEverywhere': { en: 'Replace everywhere with one value...', cs: 'Nahradit všude jednou hodnotou...', de: 'Überall durch einen Wert ersetzen...', fi: 'Korvaa kaikkialla yhdellä arvolla...' },
  'refDelete.resolveIndividually': { en: 'Resolve each flow individually...', cs: 'Vyřešit každý tok jednotlivě...', de: 'Jeden Fluss einzeln auflösen...', fi: 'Ratkaise jokainen virta erikseen...' },
  'refDelete.replaceAndDelete': { en: 'Replace & Delete', cs: 'Nahradit a smazat', de: 'Ersetzen & Löschen', fi: 'Korvaa ja poista' },
  'refDelete.applyAndDelete': { en: 'Apply & Delete', cs: 'Použít a smazat', de: 'Anwenden & Löschen', fi: 'Käytä ja poista' },
  'refDelete.removeTag': { en: 'Remove tag', cs: 'Odebrat značku', de: 'Markierung entfernen', fi: 'Poista merkintä' },
  'refDelete.replaceOnAllFlows': { en: 'Replace "{name}" with the value below on all {count} affected flow{plural}, then delete it.', cs: 'Nahraďte „{name}“ níže uvedenou hodnotou ve všech {count} dotčených tocích a poté ji smažte.', de: '„{name}“ durch den unten stehenden Wert in allen {count} betroffenen Flüssen ersetzen und dann löschen.', fi: 'Korvaa "{name}" alla olevalla arvolla kaikissa {count} vaikutuksen alaisessa virrassa ja poista se sitten.' },
  'refDelete.chooseReplacementEach': { en: 'Choose a replacement for each affected flow, or leave it as "Remove tag" to just untag it. Then delete "{name}".', cs: 'Vyberte náhradu pro každý dotčený tok, nebo ponechte „Odebrat značku“ pro pouhé odznačení. Poté smažte „{name}“.', de: 'Wählen Sie für jeden betroffenen Fluss einen Ersatz, oder belassen Sie es bei „Markierung entfernen“, um nur die Markierung zu entfernen. Löschen Sie dann „{name}“.', fi: 'Valitse korvaaja jokaiselle vaikutuksen alaiselle virralle, tai jätä "Poista merkintä" vain poistaaksesi merkinnän. Poista sitten "{name}".' },
  'refDelete.notUsedSystems': { en: "This entry isn't assigned to any system. This action can't be undone.", cs: 'Tato položka není přiřazena žádnému systému. Tuto akci nelze vrátit zpět.', de: 'Dieser Eintrag ist keinem System zugewiesen. Diese Aktion kann nicht rückgängig gemacht werden.', fi: 'Tätä merkintää ei ole määritetty millekään järjestelmälle. Tätä toimintoa ei voi kumota.' },
  'refDelete.usedBySystems': { en: 'This is assigned to {count} system(s). Deleting it will leave those systems Uncategorized unless you resolve them first.', cs: 'Toto je přiřazeno {count} systémům. Smazáním by tyto systémy zůstaly nezařazené, pokud je nejprve nevyřešíte.', de: 'Dies ist {count} System(en) zugewiesen. Beim Löschen blieben diese Systeme nicht kategorisiert, sofern Sie sie nicht vorher auflösen.', fi: 'Tämä on määritetty {count} järjestelmälle. Poistaminen jättäisi nämä järjestelmät luokittelemattomiksi, ellet ratkaise niitä ensin.' },
  'refDelete.resolveIndividuallySystems': { en: 'Resolve each system individually...', cs: 'Vyřešit každý systém jednotlivě...', de: 'Jedes System einzeln auflösen...', fi: 'Ratkaise jokainen järjestelmä erikseen...' },
  'refDelete.replaceOnAllSystems': { en: 'Replace "{name}" with the value below on all {count} affected system{plural}, then delete it.', cs: 'Nahraďte „{name}“ níže uvedenou hodnotou ve všech {count} dotčených systémech a poté ji smažte.', de: '„{name}“ durch den unten stehenden Wert in allen {count} betroffenen Systemen ersetzen und dann löschen.', fi: 'Korvaa "{name}" alla olevalla arvolla kaikissa {count} vaikutuksen alaisessa järjestelmässä ja poista se sitten.' },
  'refDelete.chooseReplacementEachSystem': { en: 'Choose a replacement for each affected system, or leave it as "Uncategorized" to just remove the tag. Then delete "{name}".', cs: 'Vyberte náhradu pro každý dotčený systém, nebo ponechte „Nezařazeno“ pro pouhé odznačení. Poté smažte „{name}“.', de: 'Wählen Sie für jedes betroffene System einen Ersatz, oder belassen Sie es bei „Nicht kategorisiert“, um nur die Markierung zu entfernen. Löschen Sie dann „{name}“.', fi: 'Valitse korvaaja jokaiselle vaikutuksen alaiselle järjestelmälle, tai jätä "Luokittelematon" vain poistaaksesi merkinnän. Poista sitten "{name}".' },
  'refDelete.removeTagSystem': { en: 'Uncategorized', cs: 'Nezařazeno', de: 'Nicht kategorisiert', fi: 'Luokittelematon' },

