  // Import / Export (Settings) - selective export of systems/objects/edges as a JSON bundle, and
  // import of one such bundle back in, with per-conflict resolution (override/skip/rename).
  'importExport.section.systems': { en: 'Systems', cs: 'Systémy', de: 'Systeme', fi: 'Järjestelmät' },
  'importExport.section.objects': { en: 'Data Objects', cs: 'Datové objekty', de: 'Datenobjekte', fi: 'Data-objektit' },
  'importExport.section.edges': { en: 'Edges', cs: 'Propojení', de: 'Verbindungen', fi: 'Yhteydet' },
  'importExport.export.title': { en: 'Export', cs: 'Export', de: 'Export', fi: 'Vienti' },
  'importExport.export.blurb': { en: 'Pick exactly the systems, data objects, and edges you want to move elsewhere. Anything they depend on (an edge’s two systems and the objects it carries, an object’s master system) is included automatically, so the file can always be imported on its own.', cs: 'Vyberte přesně ty systémy, datové objekty a propojení, které chcete přesunout jinam. Vše, na čem závisí (oba systémy propojení a objekty, které přenáší, master systém objektu), se přidá automaticky, takže soubor lze vždy importovat samostatně.', de: 'Wählen Sie genau die Systeme, Datenobjekte und Verbindungen aus, die Sie verschieben möchten. Alles, wovon sie abhängen (die beiden Systeme einer Verbindung und die von ihr transportierten Objekte, das Master-System eines Objekts), wird automatisch einbezogen, sodass die Datei immer eigenständig importierbar ist.', fi: 'Valitse tarkalleen ne järjestelmät, data-objektit ja yhteydet, jotka haluat siirtää muualle. Kaikki, mistä ne riippuvat (yhteyden molemmat järjestelmät ja sen kuljettamat objektit, objektin isäntäjärjestelmä), sisällytetään automaattisesti, joten tiedosto voidaan aina tuoda itsenäisesti.' },
  'importExport.export.searchPlaceholder': { en: 'Search...', cs: 'Hledat...', de: 'Suchen...', fi: 'Hae...' },
  'importExport.export.selectedCount': { en: '{count} selected', cs: '{count} vybráno', de: '{count} ausgewählt', fi: '{count} valittu' },
  'importExport.export.selectAll': { en: 'Select all', cs: 'Vybrat vše', de: 'Alle auswählen', fi: 'Valitse kaikki' },
  'importExport.export.clear': { en: 'Clear', cs: 'Zrušit výběr', de: 'Auswahl aufheben', fi: 'Tyhjennä valinta' },
  'importExport.export.dependencyNote': { en: 'Related systems and objects that a selected edge or object depends on are ticked automatically - shown locked (with a lock icon) below, since they can only be removed by deselecting whatever needs them.', cs: 'Související systémy a objekty, na kterých vybrané propojení nebo objekt závisí, se zaškrtnou automaticky - níže jsou zobrazeny uzamčené (se symbolem zámku), protože je lze odebrat pouze zrušením výběru toho, co je vyžaduje.', de: 'Zugehörige Systeme und Objekte, von denen eine ausgewählte Verbindung oder ein Objekt abhängt, werden automatisch markiert - unten gesperrt (mit Schlosssymbol) angezeigt, da sie nur durch Abwählen dessen entfernt werden können, was sie benötigt.', fi: 'Valitun yhteyden tai objektin riippuvuudet (liittyvät järjestelmät ja objektit) valitaan automaattisesti - ne näkyvät alla lukittuina (lukkokuvakkeella), koska ne voi poistaa vain poistamalla valinnan siltä, mikä niitä tarvitsee.' },
  'importExport.lockedHint': { en: 'Required by something else you’ve selected - deselect that first to remove this.', cs: 'Vyžadováno něčím jiným, co jste vybrali - nejprve zrušte výběr toho, abyste toto mohli odebrat.', de: 'Wird von etwas anderem benötigt, das Sie ausgewählt haben - heben Sie zuerst dessen Auswahl auf, um dies zu entfernen.', fi: 'Jokin muu valitsemasi kohde vaatii tämän - poista ensin sen valinta, jos haluat poistaa tämän.' },
  'importExport.export.button': { en: 'Export selected', cs: 'Exportovat vybrané', de: 'Auswahl exportieren', fi: 'Vie valitut' },
  'importExport.import.title': { en: 'Import', cs: 'Import', de: 'Import', fi: 'Tuonti' },
  'importExport.import.blurb': { en: 'Choose a previously exported file. You’ll see exactly what’s new versus what already exists here, and every conflict must be resolved (override, skip, or rename) before the import can start.', cs: 'Vyberte dříve exportovaný soubor. Uvidíte přesně, co je nové a co už zde existuje, a každý konflikt musí být vyřešen (přepsat, přeskočit nebo přejmenovat) před zahájením importu.', de: 'Wählen Sie eine zuvor exportierte Datei aus. Sie sehen genau, was neu ist und was bereits vorhanden ist, und jeder Konflikt muss (überschreiben, überspringen oder umbenennen) gelöst werden, bevor der Import starten kann.', fi: 'Valitse aiemmin viety tiedosto. Näet tarkalleen, mikä on uutta ja mikä on jo olemassa, ja jokainen ristiriita on ratkaistava (korvaa, ohita tai nimeä uudelleen) ennen tuonnin aloittamista.' },
  'importExport.import.chooseFile': { en: 'Choose file...', cs: 'Vybrat soubor...', de: 'Datei auswählen...', fi: 'Valitse tiedosto...' },
