  'importExport.import.invalidFile': { en: 'That file could not be read as an EA Designer export.', cs: 'Tento soubor nelze načíst jako export EA Designer.', de: 'Diese Datei konnte nicht als EA-Designer-Export gelesen werden.', fi: 'Tiedostoa ei voitu lukea EA Designer -vientinä.' },
